def minPath(grid, k):
    """
    Finds the lexicographically smallest path of length k in a grid.
    A path of length k means visiting exactly k cells.
    The path is lexicographically smallest if the sequence of values is smallest.
    """
    if k <= 0:
        return []

    n = len(grid)
    if n == 0:
        return []

    # To find the lexicographically smallest path of length k:
    # 1. The first element must be the smallest possible value in the grid, which is 1.
    # 2. The second element must be the smallest neighbor of the cell containing 1.
    # 3. The third element must be the smallest neighbor of the cell containing the second element.
    #    Since the cell containing 1 is a neighbor of the second element and 1 is the smallest 
    #    value in the grid, the third element will always be 1.
    # 4. This pattern repeats: [1, min_neighbor(1), 1, min_neighbor(1), ...]

    # Find position of 1
    start_r, start_c = -1, -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start_r, start_c = r, c
                break
        if start_r != -1:
            break

    if k == 1:
        return [1]

    # Find the smallest neighbor of 1
    min_neighbor = float('inf')
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = start_r + dr, start_c + dc
        if 0 <= nr < n and 0 <= nc < n:
            if grid[nr][nc] < min_neighbor:
                min_neighbor = grid[nr][nc]

    # The optimal path is [1, min_neighbor, 1, min_neighbor, ...]
    path = []
    for i in range(k):
        if i % 2 == 0:
            path.append(1)
        else:
            path.append(min_neighbor)

    return path
